-- Onboarding tour
('tour.step1_title',       'en', 'Welcome to KnoBitz'),
('tour.step1_title',       'et', 'Tere tulemast KnoBitz-i!'),
('tour.step1_text',        'en', 'Click any node on the map to open its sidebar. From here you can <strong>mark it as known</strong>, run a <strong>4-question knowledge test</strong>, or start a <strong>guided learning session</strong>.<br><br>The map covers the full K12 curriculum — Grades 1 through 12, all subjects. Each topic connects to what you already know and what comes next.'),
('tour.step1_text',        'et', 'Kliki mis tahes kaardi sõlmel, et avada selle külgpaneel. Sealt saad <strong>märkida selle teadaolevaks</strong>, teha <strong>4-küsimuselise teadmiste testi</strong> või alustada <strong>juhendatud õppesessiooni</strong>.<br><br>Kaart katab kogu põhikooli ja gümnaasiumi õppekava — 1. kuni 12. klassini, kõik ained. Iga teema seob sinu senised teadmised järgmiste sammudega.'),
('tour.row_zoom_in',       'en', 'Zoom in'),
('tour.row_zoom_in',       'et', 'Suumi sisse'),
('tour.row_zoom_out',      'en', 'Zoom out'),
('tour.row_zoom_out',      'et', 'Suumi välja'),
('tour.step2_text_tail',   'en', 'Drag any node to rearrange. Over 5,000 topics from the K12 national curriculum.'),
('tour.step2_text_tail',   'et', 'Lohista suvalist sõlme, et paigutust muuta. Üle 5000 teema riiklikust õppekavast.'),
('tour.step3_title',       'en', 'Map controls'),
('tour.step3_title',       'et', 'Kaardi juhtnupud'),
('tour.row_map_view',      'en', 'Map view'),
('tour.row_map_view',      'et', 'Kaardivaade'),
('tour.row_map_view_desc', 'en', 'reset to full overview'),
('tour.row_map_view_desc', 'et', 'lähtesta täisülevaatele'),
('tour.row_filters',       'en', 'Filters'),
('tour.row_filters',       'et', 'Filtrid'),
('tour.row_filters_desc',  'en', 'focus on a specific grade, subject, or learning goal'),
('tour.row_filters_desc',  'et', 'keskendu kindlale klassile, ainele või õpieesmärgile'),
('tour.step4_title',       'en', 'Learning mode & knobits'),
('tour.step4_title',       'et', 'Õpperežiim ja knobitid'),
('tour.step4_text',        'en', 'Guided learning breaks each topic into <strong>knobits</strong> — small, focused units you master one at a time. Each knobit walks you through four phases:<br><br><em>Explain → Demonstrate → Practice → Meaning</em><br><br>You set the pace. You can ask anything at any time using the field at the bottom.'),
('tour.step4_text',        'et', 'Juhendatud õpe jagab iga teema <strong>knobititeks</strong> — väikesteks fokuseeritud üksusteks, mida omandad ükshaaval. Iga knobit juhib sind läbi nelja etapi:<br><br><em>Selgitus → Näide → Harjutus → Tähendus</em><br><br>Tempo valid ise. Küsi mida iganes soovid, kasutades allosas olevat sisestusvälja.'),
('tour.demo_node_label',   'en', 'Quantum Mechanics'),
('tour.demo_node_label',   'et', 'Kvantmehaanika'),
('tour.demo_breadcrumb',   'en', 'Natural Sciences › Physics'),
('tour.demo_breadcrumb',   'et', 'Loodusteadused › Füüsika'),
('tour.demo_knobit_1',     'en', 'What is a quantum state?'),
('tour.demo_knobit_1',     'et', 'Mis on kvantolek?'),
('tour.demo_knobit_2',     'en', 'Wave-particle duality'),
('tour.demo_knobit_2',     'et', 'Laine-osakese duaalsus'),
('tour.demo_knobit_3',     'en', 'The uncertainty principle'),
('tour.demo_knobit_3',     'et', 'Määramatuse printsiip'),
('tour.demo_knobit_4',     'en', 'Quantum superposition'),
('tour.demo_knobit_4',     'et', 'Kvantsuperpositsioon'),
('tour.demo_knobit_5',     'en', 'Measurement and collapse'),
('tour.demo_knobit_5',     'et', 'Mõõtmine ja kollaps'),
('tour.step5_title',       'en', 'Your Learner Passport'),
('tour.step5_title',       'et', 'Sinu Learner Passport'),
('tour.step5_text',        'en', 'Tap the menu icon above, then click <strong>Account</strong> to open your Learner Passport — a living record of everything you learn. It tracks your progress, stores credentials, goals, and reflections across all subjects and grades.'),
('tour.step5_text',        'et', 'Puuduta ülal olevat menüüikooni ja vajuta seejärel <strong>Konto</strong>, et avada oma Learner Passport — elav ülevaade kõigest, mida oled õppinud. See jälgib sinu edenemist ning talletab tunnistusi, eesmärke ja mõtisklusi kõigi ainete ja klasside lõikes.'),
('tour.step_of',           'en', 'Step {n} of {total}'),
('tour.step_of',           'et', 'Samm {n}/{total}'),
('tour.skip',              'en', 'Skip tour'),
('tour.skip',              'et', 'Jäta tuur vahele'),
('tour.back',              'en', '← Back'),
('tour.back',              'et', '← Tagasi'),
('tour.next',              'en', 'Next →'),
('tour.next',              'et', 'Edasi →'),
('tour.done',              'en', 'Done ✓'),
('tour.done',              'et', 'Valmis ✓'),
('tour.overlay_hint',      'en', 'The app is available after the tour. Use Next → to continue.'),
('tour.overlay_hint',      'et', 'Rakendus on saadaval pärast tuuri lõppu. Jätka nupuga Edasi →.'),

-- Tour rebuild (7 steps) — new steps only; step1/step3/step4/demo_* etc. above are reused unchanged
('tour.welcome_title', 'en', 'The knowledge map'),
('tour.welcome_title', 'et', 'Teadmiste kaart'),
('tour.welcome_text', 'en', 'Welcome to KnoBitz! This is a learning app covering the full curriculum from grade 1 through grade 12 — every subject, one map. Everyone learns exactly what they need, at their own pace.'),
('tour.welcome_text', 'et', 'Tere tulemast KnoBitzi! See on õpirakendus, mis katab kogu õppekava 1. klassist 12. klassini — kõik ained, üks kaart. Igaüks õpib täpselt seda, mida vajab, endale sobivas tempos.'),
('tour.row_search', 'en', 'Search'),
('tour.row_search', 'et', 'Otsing'),
('tour.row_search_desc', 'en', 'quickly find any topic on the map'),
('tour.row_search_desc', 'et', 'leia kiiresti mistahes teema kaardilt'),
('tour.menu_title', 'en', 'Menu & Anne'),
('tour.menu_title', 'et', 'Menüü ja Anne'),
('tour.menu_text', 'en', 'The ☰ menu takes you to your Learner Passport, notifications, settings, and help. Anne lives in the bottom right — your study companion, ready to help with anything, any time.'),
('tour.menu_text', 'et', '☰ menüüst pääsed oma Õppija passi, teadete, seadete ja abiinfoni. Paremal all elab Anne — sinu õpikaaslane, kellelt võid igal ajal küsida abi mistahes teema kohta.'),
('tour.learning_title', 'en', 'Learning'),
('tour.learning_title', 'et', 'Õppimine'),
('tour.learning_text', 'en', 'This is what one step of your learning journey looks like. You read a short piece (a knobit) and choose how to continue: <strong>got it</strong> if it made sense, <strong>simpler</strong> if you need it explained differently, or <strong>go deeper</strong> if you want more. The box below is always open for a question, any time something is unclear.'),
('tour.learning_text', 'et', 'Nii näeb välja üks samm sinu õpiteekonnal. Loed lühikest tükki (knobitit) ja valid, kuidas edasi minna: <strong>selge</strong>, kui said aru, <strong>lihtsamalt</strong>, kui vaja veel selgitust, või <strong>keerulisemalt</strong>, kui tahad sügavamale minna. All olevasse kasti võid igal hetkel kirjutada küsimuse, kui midagi jääb segaseks.'),
('tour.passport_title', 'en', 'Learner Passport'),
('tour.passport_title', 'et', 'Õppija pass'),
('tour.passport_text', 'en', 'Your Learner Passport describes who you are — age, interests, values, learning style. Everything KnoBitz explains to you, and every test it builds, adapts based on this, so learning actually fits you.'),
('tour.passport_text', 'et', 'Sinu Õppija pass kirjeldab, kes sa oled — vanus, huvid, väärtused, õpistiil. Kõik, mida KnoBitz sulle selgitab, ja iga test, mille koostab, kohandub selle põhjal, et õppimine oleks just sulle sobiv.'),
('tour.demo_byte_1', 'en', 'A quantum state describes everything that can be known about a particle — like its energy or position — before it is measured. Unlike everyday objects, a particle does not have one fixed value before measurement; it holds many possible states at once.'),
('tour.demo_byte_1', 'et', 'Kvantolek kirjeldab kõike, mida on võimalik teada osakese kohta — näiteks selle energiat või asukohta — enne kui seda mõõdetakse. Erinevalt igapäevastest asjadest ei ole osakesel enne mõõtmist üht kindlat väärtust, vaid hulk võimalikke olekuid korraga.'),
('tour.demo_visual_caption', 'en', 'Example diagram'),
('tour.demo_visual_caption', 'et', 'Näidisjoonis'),

-- Anne (mentor chat widget)
('anne.input_placeholder', 'en', 'Ask Anne...'),
('anne.input_placeholder', 'et', 'Küsi Annelt...'),
('anne.error',             'en', 'Something went wrong — please try again.'),
('anne.error',             'et', 'Midagi läks valesti — palun proovi uuesti.'),

-- Help page (nav item + Getting Started guide)
('nav.help',                  'en', 'Help'),
('nav.help',                  'et', 'Abi'),
('help.hero_title',           'en', 'The fastest way to get help'),
('help.hero_title',           'et', 'Kiireim viis abi saada'),
('help.hero_sub',             'en', 'Ask Anne directly — she knows exactly how KnoBitz works and can help right away. Her chat window is in the bottom right.'),
('help.hero_sub',             'et', 'Küsi otse Anne käest — ta teab täpselt, kuidas KnoBitz töötab, ja aitab sind kohe. Tema vestlusaken on paremal all.'),
('help.reading_note',         'en', 'Prefer to read it yourself instead? Here\'s a written guide.'),
('help.reading_note',         'et', 'Eelistad pigem ise lugeda? Siin on kirjalik juhend.'),
('help.map_title',            'en', 'The map'),
('help.map_title',            'et', 'Kaart'),
('help.map_body',             'en', 'You\'ll see an interactive knowledge map with five levels — from broad domains (L1) down to individual concepts (L5). Drag and zoom the map, search for concepts in the top search box, and use the filters (e.g. grade band, subject) and layers on the left to make the map clearer.'),
('help.map_body',             'et', 'Näed interaktiivset teadmiste kaarti viie tasemega — laiadest valdkondadest (L1) kuni üksikute mõisteteni (L5). Kaarti saab lohistada ja suumida. Mõisteid saab otsida ülal otsingukastist. Vasakul asuvad filtrid (nt põhikool, gümnaasium, aine) ja kihid, mis aitavad kaarti selgemaks muuta.'),
('help.node_title',           'en', 'Clicking a concept'),
('help.node_title',           'et', 'Mõistel klikkimine'),
('help.node_body',            'en', 'Clicking a concept opens a side panel. Which buttons you see depends on its level:'),
('help.node_body',            'et', 'Kui klikid mõistel, avaneb külgpaneel. Nupud, mida näed, sõltuvad mõiste tasemest:'),
('help.node_l1',              'en', 'L1 (domain): no buttons — pick a subtopic.'),
('help.node_l1',              'et', 'L1 (valdkond): nuppe pole — vali mõni alamteema.'),
('help.node_l2',              'en', 'L2: "Learn this" shows a recommended learning order for its subtopics, with a "Sounds good" button that jumps to the first recommended one.'),
('help.node_l2',              'et', 'L2: „Õpin seda" näitab soovitatud õpijärjekorda alamteemadest, koos nupuga „Sobib", mis viib esimese soovitatud teema juurde.'),
('help.node_l34',             'en', 'L3 and L4: "Set as goal" adds the topic to your goals. "Learn this" opens a structured learning path that walks step by step down to individual lessons.'),
('help.node_l34',             'et', 'L3 ja L4: „Sea eesmärgiks" lisab teema sinu eesmärkide hulka. „Õpin seda" avab struktureeritud õpiraja, mis viib samm-sammult üksikute õppetundideni.'),
('help.node_l45',             'en', 'L4 and L5: "Test me" starts a short 4-question diagnostic test.'),
('help.node_l45',             'et', 'L4 ja L5: „Teen testi" käivitab lühikese 4-küsimuselise diagnostilise testi.'),
('help.node_l5',              'en', 'L5 (individual concept): "Learn this" opens the lesson. The "I know this" toggle lets you mark that you already know it.'),
('help.node_l5',              'et', 'L5 (üksikmõiste): „Õpin seda" avab õppetunni. „Tean seda" lüliti lubab sul ise märkida, et oskad seda juba.'),
('help.lesson_title',         'en', 'The lesson'),
('help.lesson_title',         'et', 'Õppetund'),
('help.lesson_body',          'en', 'Every lesson has four parts: explanation, example, practice, and meaning (why it matters). At any point you can say "too simple" or "too complex," ask for a different explanation, or ask questions directly inside the lesson via the ask bar.'),
('help.lesson_body',          'et', 'Iga õppetund koosneb neljast osast: selgitus, näide, harjutus ja tähendus (miks see oluline on). Igal hetkel saad öelda „liiga lihtne" või „liiga keeruline", paluda teistsugust selgitust, või küsida küsimusi otse tunni sees, küsimuste riba kaudu.'),
('help.test_title',           'en', 'Testing'),
('help.test_title',           'et', 'Testimine'),
('help.test_body',            'en', 'The "Test me" button starts a 4-question adaptive diagnostic test that adjusts to your answers and gives you a read on how well you know the topic.'),
('help.test_body',            'et', '„Teen testi" nupp käivitab 4-küsimuselise adaptiivse diagnostilise testi, mis kohandub sinu vastuste järgi ja annab lõpuks hinnangu, kui hästi seda teemat oskad.'),
('help.goals_title',          'en', 'Goals and your Learner Passport'),
('help.goals_title',          'et', 'Eesmärgid ja Õppijapass'),
('help.goals_body',           'en', 'Goals, progress, achievements, points ("lumens"), and rank are all on your Learner Passport — open it from the menu (☰ icon, top right) under "Account." From there you can also link your account to a teacher or parent with an invite code so they can see your progress.'),
('help.goals_body',           'et', 'Eesmärgid, edenemine, saavutused, luumenid ja järgud on koos näha Õppijapassis — see avaneb menüüst (☰ ikoon üleval paremal) valikust „Konto". Sealt saad ka ühendada oma konto õpetaja või lapsevanemaga ühenduskoodi abil, et nemad näeksid sinu edenemist.'),
('help.notif_settings_title', 'en', 'Notifications and settings'),
('help.notif_settings_title', 'et', 'Teavitused ja seaded'),
('help.notif_settings_body',  'en', 'The same menu has Notifications (reminders and achievements) and Settings (font size, language, colour palette, focus timer, ambient sound).'),
('help.notif_settings_body',  'et', 'Sama menüü alt leiad ka Teavitused (meeldetuletused ja saavutused) ning Seaded (fondisuurus, keel, värvipalett, fookustaimer, taustaheli).'),
-- Four-alternatives redesign of the Help page (replaces the old hero/divider layout).
('help.page_title',           'en', 'How can we help?'),
('help.page_title',           'et', 'Kuidas saame aidata?'),
('help.page_sub',             'en', 'Pick whichever fits how you like to get up to speed.'),
('help.page_sub',             'et', 'Vali endale sobivaim viis, kuidas kiiresti kohaneda.'),
('help.opt_anne_title',       'en', 'Ask Anne'),
('help.opt_anne_title',       'et', 'Küsi Annelt'),
('help.opt_anne_desc',        'en', 'She knows the app, your own learning, and the subjects — and answers right away.'),
('help.opt_anne_desc',        'et', 'Ta teab nii äppi, sinu õppimist kui ka õppeaineid — ja vastab kohe.'),
('help.opt_tour_title',       'en', 'Take the tour'),
('help.opt_tour_title',       'et', 'Vaata tutvustust'),
('help.opt_tour_desc',        'en', 'A short guided walkthrough of the app, right on the map.'),
('help.opt_tour_desc',        'et', 'Lühike juhitud tutvustus otse kaardil.'),
('help.opt_doc_title',        'en', 'Read the guide'),
('help.opt_doc_title',        'et', 'Loe juhendit'),
('help.opt_doc_desc',         'en', 'A written, step-by-step overview you can skim at your own pace.'),
('help.opt_doc_desc',         'et', 'Kirjalik samm-sammuline ülevaade, mida saad lugeda oma tempos.'),
('help.opt_video_title',      'en', 'Watch the video'),
('help.opt_video_title',      'et', 'Vaata videot'),
('help.opt_video_desc',       'en', 'A short video walkthrough.'),
('help.opt_video_desc',       'et', 'Lühike videotutvustus.'),
('help.soon',                 'en', 'Coming soon'),
('help.soon',                 'et', 'Peagi')

